// MCP tools for batch 80 (3-Nov-2026): printable habit trackers and badges / emblems.
// The pure cores come from src/tools_core80.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/
// printpdf-core-72d.js, habit-core-80c.js, draw-core-67d.js, icons-72c.js, icons-78.js, badge-core-80d.js) — one source of truth with the
// /tools/ pages habit-tracker-template and badge-maker. Stateless: no D1/R2, no fetch. Badge lettering uses the core's fallback shaper
// (base-14 SVG text set along the ring), so no font download is needed.
import { MGD80C, MGD80D, MGD72Icons } from "./tools_core80.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => ({ content: [{ type: "text", text }], structuredContent });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const OUT_CAP = 120 * 1024, TOTAL_CAP = 240 * 1024;
const num = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
const int = (v, a, b) => Number.isInteger(num(v)) && num(v) >= a && num(v) <= b;
const H = MGD80C.habit, B = MGD80D, ICONS = Object.keys(MGD72Icons.icons);
const VIEWS = Object.keys(H.VIEWS), HSTYLES = Object.keys(H.STYLES), HPAPER = Object.keys(H.PAPER);
const SCHEMES = Object.keys(B.SCHEMES), ORN = ["none", "stars", "dots", "stars3"], CENTER = ["icon", "initials", "text", "star"], RING = ["single", "double", "none"];

export const TOOL_DEFS = [
  {
    name: "make_habit_tracker",
    description: "Use when someone wants a printable habit tracker: monthly (habits × every day of the month), weekly (one page per week with the dates filled in) or yearly (one page per habit, 12 months × 31 days), for any month and year, week starting Monday or Sunday, 1-20 habits (named or blank lines), minimal, dot-grid or pastel style, on Letter, A4 or A5. Returns the calendar facts and a true-size SVG per page.",
    inputSchema: {
      type: "object",
      properties: {
        layout: { type: "string", enum: VIEWS, description: "Default monthly." },
        year: { type: "integer", description: "1900-2200 (default 2026)." },
        month: { type: "integer", description: "1-12 (default 11)." },
        week_start: { type: "string", enum: ["mon", "sun"], description: "Default mon." },
        habits: { type: "array", items: { type: "string" }, description: "Up to 20 names; blank strings = blank lines." },
        count: { type: "integer", description: "Blank lines 1-20 (instead of habits)." },
        title: { type: "string" },
        style: { type: "string", enum: HSTYLES },
        paper: { type: "string", enum: HPAPER, description: "Default letter." },
        orientation: { type: "string", enum: ["auto", "portrait", "landscape"], description: "auto = landscape except weekly." },
      },
    },
    annotations: RO("Habit tracker"),
  },
  {
    name: "make_badge",
    description: "Use when a brand, club, café, team or event needs a badge or emblem: circle, shield, hexagon, ribbon, starburst or rosette, with top and bottom text curved along the ring, an icon, initials, a word or a star in the middle, an EST. line, star or dot ornaments and ten colour schemes. Returns the SVG (decorative designs, not official seals).",
    inputSchema: {
      type: "object",
      properties: {
        shape: { type: "string", enum: B.SHAPES, description: "Default circle." },
        top: { type: "string", description: "Top arc text." },
        bottom: { type: "string", description: "Bottom arc text." },
        center: { type: "string", enum: CENTER, description: "Default icon." },
        icon: { type: "string", description: "Lucide name, e.g. coffee, heart (default star)." },
        center_text: { type: "string", description: "Up to 3 lines, or the ribbon band." },
        initials: { type: "string" },
        est: { type: "string", description: "Small line, e.g. EST. 2026." },
        ornament: { type: "string", enum: ORN, description: "Default stars." },
        ring: { type: "string", enum: RING },
        scheme: { type: "string", enum: SCHEMES, description: "Colours (default navy)." },
        size_mm: { type: "number", description: "20-300 (default 100)." },
      },
    },
    annotations: RO("Badge"),
  },
];

export const NEXT80 = {
  make_habit_tracker: "Next step: open the habit tracker link to change the colours and download the vector PDF with every page.",
  make_badge: "Next step: open the badge maker link to choose real lettering fonts, export outlined SVG, PNG up to 4096 px or a sticker sheet.",
};

// ---- habit tracker
function habit(a) {
  if (a.layout !== undefined && !VIEWS.includes(a.layout)) return err("layout must be monthly, weekly or yearly.");
  if (a.year !== undefined && !int(a.year, 1900, 2200)) return err("year must be an integer 1900-2200.");
  if (a.month !== undefined && !int(a.month, 1, 12)) return err("month must be an integer 1-12.");
  if (a.week_start !== undefined && !["mon", "sun"].includes(a.week_start)) return err("week_start must be mon or sun.");
  if (a.style !== undefined && !HSTYLES.includes(a.style)) return err("style must be one of: " + HSTYLES.join(", ") + ".");
  if (a.paper !== undefined && !HPAPER.includes(a.paper)) return err("paper must be one of: " + HPAPER.join(", ") + ".");
  if (a.orientation !== undefined && !["auto", "portrait", "landscape"].includes(a.orientation)) return err("orientation must be auto, portrait or landscape.");
  if (a.habits !== undefined && !(Array.isArray(a.habits) && a.habits.length >= 1 && a.habits.length <= 20 && a.habits.every((x) => typeof x === "string"))) return err("habits must be an array of 1-20 strings.");
  if (a.count !== undefined && (!int(a.count, 1, 20) || a.habits !== undefined)) return err("count must be an integer 1-20 (and not with habits).");
  const names = a.habits ? a.habits.map((x) => str(x, 60).replace(/[\r\n]+/g, " ")) : null;
  const o = { view: a.layout || "monthly", year: a.year !== undefined ? num(a.year) : 2026, month: a.month !== undefined ? num(a.month) : 11, start: a.week_start || "mon",
    habits: names ? names.length : a.count !== undefined ? num(a.count) : 8, names: names ? names.join("\n") : a.count !== undefined ? "" : undefined, style: a.style || "minimal", paper: a.paper || "letter", orient: a.orientation || "auto" };
  if (a.title !== undefined) o.title = str(a.title, 40);
  Object.keys(o).forEach((k) => o[k] === undefined && delete o[k]);
  const L = H.layout(o), r = L.opts, mname = H.MONTHS[r.month - 1], nd = H.daysIn(r.year, r.month - 1), first = H.DAYS[H.dow(r.year, r.month - 1, 1)];
  const page = `${T}/habit-tracker-template/`, size = `${L.paper} ${r.land ? "landscape" : "portrait"} (${L.size_mm.map((v) => Math.round(v * 10) / 10).join(" × ")} mm)`;
  const lines = [], sc = { layout: r.view, year: r.year, month: r.month, month_name: mname, days_in_month: nd, first_weekday: first, week_start: r.start === "sun" ? "Sunday" : "Monday",
    habits: r.list, style: r.style, paper: r.paper, orientation: r.land ? "landscape" : "portrait", page_mm: L.size_mm.map((v) => Math.round(v * 10) / 10), pages: L.pages.length, page };
  if (r.view === "monthly") {
    lines.push(`**Monthly habit tracker, ${mname} ${r.year}: ${r.habits} habit rows × ${nd} days (the 1st is a ${first}), on ${size}.**`, `Cells ${L.pages[0].meta.cell_mm.join(" × ")} mm, weekends in the accent colour, a total column and a notes box.`);
    sc.cell_mm = L.pages[0].meta.cell_mm;
  } else if (r.view === "weekly") {
    const weeks = H.weeksOf(o).map((w) => w.map((d) => `${d[0]}-${String(d[1] + 1).padStart(2, "0")}-${String(d[2]).padStart(2, "0")}`));
    lines.push(`**Weekly habit tracker, ${mname} ${r.year}: ${weeks.length} weeks (${sc.week_start} start) overlapping the month, one page each, ${r.habits} habits, on ${size}.**`,
      ...weeks.map((w, i) => `- Week ${i + 1}: ${w[0]} to ${w[6]}`));
    sc.weeks = weeks;
  } else {
    const leap = H.daysIn(r.year, 1) === 29;
    lines.push(`**Yearly habit tracker ${r.year}: one page per habit (${r.habits} pages), 12 months × 31 days, on ${size}.**`,
      `${leap ? "Leap year: 366" : "365"} days; the ${12 * 31 - (leap ? 366 : 365)} cells past each month's last day are greyed out.`);
    sc.days_in_year = leap ? 366 : 365; sc.off_cells = 12 * 31 - sc.days_in_year;
  }
  const svgs = L.pages.map((p) => H.svg(p)), inl = [];
  let total = 0;
  svgs.forEach((s, i) => { if (s.length <= OUT_CAP && total + s.length <= TOTAL_CAP) { total += s.length; inl.push(i); } });
  inl.forEach((i) => lines.push(svgs.length > 1 ? `Page ${i + 1} of ${svgs.length} (true size, ${Math.round(svgs[i].length / 1024)} KB):` : `SVG (true size, ${Math.round(svgs[i].length / 1024)} KB):`, fence("svg", svgs[i])));
  if (inl.length < svgs.length) lines.push(`${svgs.length - inl.length} of ${svgs.length} pages are not returned inline (too large together): the page link prints every page as one PDF.`);
  sc.svgs = inl.map((i) => svgs[i]); sc.svg_pages = inl.map((i) => i + 1);
  lines.push("Colours, accent and a multi-page vector PDF: " + page);
  return ok(lines.join("\n"), sc);
}

// ---- badge
function badge(a) {
  if (a.shape !== undefined && !B.SHAPES.includes(a.shape)) return err("shape must be one of: " + B.SHAPES.join(", ") + ".");
  if (a.center !== undefined && !CENTER.includes(a.center)) return err("center must be one of: " + CENTER.join(", ") + ".");
  if (a.ornament !== undefined && !ORN.includes(a.ornament)) return err("ornament must be one of: " + ORN.join(", ") + ".");
  if (a.ring !== undefined && !RING.includes(a.ring)) return err("ring must be single, double or none.");
  if (a.scheme !== undefined && !SCHEMES.includes(a.scheme)) return err("scheme must be one of: " + SCHEMES.join(", ") + ".");
  if (a.icon !== undefined && !ICONS.includes(a.icon)) return { content: [{ type: "text", text: `Unknown icon "${str(a.icon, 40)}": see structuredContent.icons for the ${ICONS.length} names.` }], structuredContent: { icons: ICONS }, isError: true };
  if (a.size_mm !== undefined && !(Number.isFinite(num(a.size_mm)) && num(a.size_mm) >= 20 && num(a.size_mm) <= 300)) return err("size_mm must be 20-300.");
  const f = { shape: a.shape || "circle", scheme: a.scheme || "navy", top: str(a.top !== undefined ? a.top : "Your Name", 80), bottom: str(a.bottom !== undefined ? a.bottom : "", 80),
    ornament: a.ornament || "stars", center: a.center || "icon", icon: a.icon || "star", centerText: str(a.center_text, 120), initials: str(a.initials, 4), est: str(a.est, 30), ring: a.ring === "single" ? undefined : a.ring };
  const d = B.badge(f), size = a.size_mm !== undefined ? num(a.size_mm) : 100, title = "Badge: " + (f.top || f.shape);
  const svg = B.svg(d, size, title), page = `${T}/badge-maker/`, sc0 = B.SCHEMES[f.scheme];
  const lines = [`**${f.shape[0].toUpperCase() + f.shape.slice(1)} badge, ${sc0.label.toLowerCase()}, ${size} × ${size} mm: ${d.lines.map((l) => `"${l}"`).join(", ") || "no text"}.**`,
    ...d.warnings.map((w) => "Note: " + w)];
  const sc = { shape: f.shape, scheme: f.scheme, colors: { fill: sc0.fill, ink: sc0.ink, line: sc0.line, accent: sc0.accent }, ornament: f.ornament, center: f.center, icon: f.center === "icon" ? f.icon : null, text_lines: d.lines, warnings: d.warnings, size_mm: size, page };
  if (svg.length <= OUT_CAP) { lines.push(`SVG (${Math.round(svg.length / 1024)} KB; lettering is live text in system fonts):`, fence("svg", svg)); sc.svg = svg; }
  else { lines.push("The SVG is too large to return inline: open the page to download it."); sc.svg_too_large = true; }
  lines.push("Real lettering fonts, outlined SVG, PNG and sticker sheets: " + page);
  return ok(lines.join("\n"), sc);
}

const HANDLERS = { make_habit_tracker: habit, make_badge: badge };
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools80Tool(name) { return NAMES.has(name); }
export async function callTools80Tool(name, a) {
  a = a && typeof a === "object" ? a : {};
  try {
    if (HANDLERS[name]) return HANDLERS[name](a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
